### Recursive Descent Parser

```xiom
pub type Parser = {
  lexer: Lexer;
  current: Token;
}

impl Parser {
  fn parse_function(self: &mut Parser) -> Function {
    self.expect(Token::Fn);
    let name = self.expect_identifier();
    self.expect(Token::LParen);
    let params = self.parse_parameters();
    self.expect(Token::RParen);
    self.expect(Token::Arrow);
    let ret_type = self.parse_type();
    self.expect(Token::LBrace);
    let body = self.parse_block();
    self.expect(Token::RBrace);
    return Function{ name: name, params: params, ret_type: ret_type, body: body };
  }

  fn parse_expression(self: &mut Parser) -> Expr {
    let left = self.parse_primary();
    return self.parse_binary_op(left, 0);
  }

  fn parse_binary_op(self: &mut Parser, left: Expr, min_prec: Int) -> Expr {
    var expr = left;
    while self.is_binary_op() && self.precedence() >= min_prec {
      let op = self.current;
      self.advance();
      let right = self.parse_primary();
      while self.is_binary_op() && self.precedence() > op.precedence() {
        right = self.parse_binary_op(right, op.precedence() + 1);
      }
      expr = BinaryExpr{ left: expr, op: op, right: right };
    }
    return expr;
  }
}
```

### Operator Precedence (Pratt Parsing)

| Precedence | Operators |
|-----------|-----------|
| 1 (lowest) | `=` (assignment) |
| 2 | `\|\|` (or) |
| 3 | `&&` (and) |
| 4 | `==`, `!=`, `<`, `>`, `<=`, `>=` |
| 5 | `+`, `-` |
| 6 | `*`, `/`, `%` |
| 7 (highest) | `!`, `-` (unary) |

### AST Node Types

```xiom
pub enum Expr {
  IntLiteral(value: Int),
  StrLiteral(value: Str),
  Identifier(name: Str),
  BinaryOp(left: Expr, op: BinOp, right: Expr),
  UnaryOp(op: UnaryOp, expr: Expr),
  Call(func: Expr, args: Vec[Expr]),
  If(cond: Expr, then: Block, else: Option[Block]),
  Match(expr: Expr, arms: Vec[MatchArm]),
  Block(stmts: Vec[Stmt]),
}
```

