fn evaluate(s: Str) -> Int {
  // 1 + 2 * 3 → 1 + (2 * 3) → 1 + 6 → 7
  // Simple: find the '+' after accounting for '*' precedence
  if s.contains("*") {
    let parts = s.split('+');
    let left = parts[0].trim();
    let right = parts[1].trim();
    if right.contains("*") {
      let mul_parts = right.split('*');
      let a = mul_parts[0].trim().parse_int().unwrap();
      let b = mul_parts[1].trim().parse_int().unwrap();
      return left.trim().parse_int().unwrap() + a * b;
    }
  }
  return 0;
}

fn main() -> Int {
  return evaluate("1 + 2 * 3");
}
